using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Payments.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.Payments.Queries.GetPayments;public sealed class GetPaymentsQueryHandler(IPaymentRepository repository):IRequestHandler<GetPaymentsQuery,Result<IReadOnlyList<PaymentDto>>>{public async Task<Result<IReadOnlyList<PaymentDto>>>Handle(GetPaymentsQuery request,CancellationToken cancellationToken)=>Result.Success<IReadOnlyList<PaymentDto>>((await repository.GetAllAsync(cancellationToken)).Select(PaymentDto.FromEntity).ToList());}
